 "content": "def transform(grid):
    """Expand the input 2 into a downward V; fill its 4-spaced inner rays with 1."""
    n = len(grid[0])
    center = next((i for i, value in enumerate(grid[0]) if value == 2), n // 2)
    out = [[0 for _ in range(n)] for _ in range(n)]

    for r in range(n):
        # The original 2 spreads down-left and down-right.
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2

        # Between the V's arms, 1s follow a diagonal ray every four columns.
        lo = max(0, center - r)
        hi = min(n - 1, center + r)
        for c in range(lo, hi + 1):
            if (c - r - center) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1

